/*
Package predicate used to create interpreted mini languages with Go syntax - mostly to define
various predicates for configuration, e.g. Latency() > 40 || ErrorRate() > 0.5.

Here's an example of fully functional predicate language to deal with division remainders:

	    // takes number and returns true or false
	    type numberPredicate func(v int) bool

	    // Converts one number to another
	    type numberMapper func(v int) int

	    // Function that creates predicate to test if the remainder is 0
	    func divisibleBy(divisor int) numberPredicate {
		    return func(v int) bool {
			    return v%divisor == 0
	        }
	    }

	    // Function - logical operator AND that combines predicates
	    func numberAND(a, b numberPredicate) numberPredicate {
	        return func(v int) bool {
	            return a(v) && b(v)
	        }
	    }

	    p, err := NewParser(Def{
			Operators: Operators{
				AND: numberAND,
			},
			Functions: map[string]interface{}{
				"DivisibleBy": divisibleBy,
			},
		})

		pr, err := p.Parse("DivisibleBy(2) && DivisibleBy(3)")
	    if err == nil {
	        fmt.Fatalf("Error: %v", err)
	    }
	    pr.(numberPredicate)(2) // false
	    pr.(numberPredicate)(3) // false
	    pr.(numberPredicate)(6) // true
*/
package predicate

// Def defines parser context including supported operators, functions, methods,
// identifiers, and property accessors.
type Def struct {
	Operators Operators
	// Function matching is case sensitive, e.g. Len is different from len
	Functions map[string]interface{}
	// Methods is a map of method names to their implementation.
	Methods map[string]interface{}
	// GetIdentifier returns value of any identifier passed in the form
	// []string{"id", "field", "subfield"}
	GetIdentifier GetIdentifierFn
	// GetProperty returns property from a map
	GetProperty GetPropertyFn
}

// GetIdentifierFn function returns identifier based on selector
// e.g. id.field.subfield will be passed as.
// GetIdentifierFn([]string{"id", "field", "subfield"}).
type GetIdentifierFn func(selector []string) (interface{}, error)

// GetPropertyFn returns property from a mapVal by key keyVal.
type GetPropertyFn func(mapVal, keyVal interface{}) (interface{}, error)

// Operators contain functions for equality and logical comparison.
type Operators struct {
	EQ  interface{}
	NEQ interface{}

	LT interface{}
	GT interface{}

	LE interface{}
	GE interface{}

	OR  interface{}
	AND interface{}
	NOT interface{}
}

// Parser takes the string with expression and calls the operators and functions.
type Parser interface {
	Parse(string) (interface{}, error)
}

package predicate

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"reflect"
	"strconv"
	"strings"

	"github.com/gravitational/trace"
)

func NewParser(d Def) (Parser, error) {
	return &predicateParser{d: d}, nil
}

type predicateParser struct {
	d Def
}

func (p *predicateParser) Parse(in string) (interface{}, error) {
	expr, err := parser.ParseExpr(in)
	if err != nil {
		return nil, err
	}

	return p.parse(expr)
}

func (p *predicateParser) parse(expr ast.Expr) (interface{}, error) {
	switch n := expr.(type) {
	case *ast.BinaryExpr:
		val, err := p.parseBinaryExpr(n)
		return val, trace.Wrap(err)

	case *ast.ParenExpr:
		val, err := p.parse(n.X)
		return val, trace.Wrap(err)

	case *ast.UnaryExpr:
		val, err := p.parseUnaryExpr(n)
		return val, trace.Wrap(err)

	case *ast.BasicLit:
		val, err := literalToValue(n)
		return val, trace.Wrap(err)

	case *ast.IndexExpr:
		val, err := p.parseIndexExpr(n)
		return val, trace.Wrap(err)

	case *ast.SelectorExpr:
		val, err := p.parseSelectorExpr(n)
		return val, trace.Wrap(err)

	case *ast.Ident:
		if p.d.GetIdentifier == nil {
			return nil, trace.NotFound("%v is not defined", n.Name)
		}
		val, err := p.d.GetIdentifier([]string{n.Name})
		return val, trace.Wrap(err)

	case *ast.CallExpr:
		val, err := p.parseCallExpr(n)
		return val, trace.Wrap(err)

	default:
		return nil, trace.BadParameter("%T is not supported", expr)
	}
}

func (p *predicateParser) parseBinaryExpr(expr *ast.BinaryExpr) (interface{}, error) {
	x, err := p.parse(expr.X)
	if err != nil {
		return nil, err
	}

	y, err := p.parse(expr.Y)
	if err != nil {
		return nil, err
	}

	val, err := p.joinPredicates(expr.Op, x, y)
	return val, trace.Wrap(err)
}

func (p *predicateParser) parseUnaryExpr(expr *ast.UnaryExpr) (interface{}, error) {
	joinFn, err := p.getJoinFunction(expr.Op)
	if err != nil {
		return nil, err
	}

	node, err := p.parse(expr.X)
	if err != nil {
		return nil, err
	}

	val, err := callFunction(joinFn, []interface{}{node})
	return val, trace.Wrap(err)
}

func (p *predicateParser) parseIndexExpr(expr *ast.IndexExpr) (interface{}, error) {
	if p.d.GetProperty == nil {
		return nil, trace.NotFound("properties are not supported")
	}

	mapVal, err := p.parse(expr.X)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	keyVal, err := p.parse(expr.Index)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	val, err := p.d.GetProperty(mapVal, keyVal)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return val, nil
}

func (p *predicateParser) evaluateArguments(nodes []ast.Expr) ([]interface{}, error) {
	out := make([]interface{}, len(nodes))
	for i, n := range nodes {
		val, err := p.parse(n)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		out[i] = val
	}
	return out, nil
}

func (p *predicateParser) parseSelectorExpr(expr *ast.SelectorExpr) (interface{}, error) {
	fields, err := evaluateSelector(expr, []string{})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if p.d.GetIdentifier == nil {
		return nil, trace.NotFound("%v is not defined", strings.Join(fields, "."))
	}

	val, err := p.d.GetIdentifier(fields)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return val, nil
}

// evaluateSelector recursively evaluates the selector field and returns a list
// of properties at the end.
func evaluateSelector(sel *ast.SelectorExpr, fields []string) ([]string, error) {
	fields = append([]string{sel.Sel.Name}, fields...)
	switch l := sel.X.(type) {
	case *ast.SelectorExpr:
		return evaluateSelector(l, fields)

	case *ast.Ident:
		fields = append([]string{l.Name}, fields...)
		return fields, nil

	default:
		return nil, trace.BadParameter("unsupported selector type: %T", l)
	}
}

func (p *predicateParser) parseCallExpr(expr *ast.CallExpr) (interface{}, error) {
	fn, args, err := p.getFunctionAndArgs(expr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	arguments, err := p.evaluateArguments(args)
	if err != nil {
		return nil, err
	}

	val, err := callFunction(fn, arguments)
	return val, trace.Wrap(err)
}

func (p *predicateParser) getFunction(name string) (interface{}, error) {
	v, ok := p.d.Functions[name]
	if !ok {
